const { DataSource, EntitySchema } = require("typeorm");
const User = new EntitySchema({ name: "User", columns: { id: { type: Number, primary: true, generated: true }, email: { type: String } } });
module.exports = { default: new DataSource({ type: "better-sqlite3", database: "dev.db", entities: [User], migrations: [__dirname + "/migrations/*.js"] }) };
